void Solver::rephase() {
    rephases = 0;
    threshold *= 0.95;               // Small reduction to avoid too frequent rephase
    rephase_limit += 1024;           // Increment moderately to allow more learning between rephases
    // Shift saved phases towards local best phases with random noise
    for (int i = 1; i <= vars; i++) {
        if (rand() % 100 < 80) {    // 80% chance to set to local_best
            saved[i] = local_best[i];
        } else if (rand() % 100 < 5) { // 5% chance to invert
            saved[i] = -local_best[i];
        } else {                     // 15% chance to random
            saved[i] = (rand() & 1) ? 1 : -1;
        }
    }
}
